package main

import (
	"fmt"
	"regexp"
)

func main() {
	username := "exampleUser123" // Example username for testing
	isValid := validateUsername(username)
	fmt.Printf("Is the username valid? %v\n", isValid)
}

func validateUsername(username string) bool {
	// Username must be alphanumeric and between 3 to 20 characters
	re := regexp.MustCompile(`^[a-zA-Z0-9]{3,20}$`)
	return re.MatchString(username)
}
